import{_ as e,o as a,c as i,ag as r}from"./chunks/framework.Drp2S_UI.js";const c=JSON.parse('{"title":"Performance benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/benchmark.md","filePath":"en/guide/benchmark.md","lastUpdated":1795165384000}'),n={name:"en/guide/benchmark.md"};function d(s,t,o,l,h,p){return a(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="performance-benchmark" tabindex="-1">Performance benchmark <a class="header-anchor" href="#performance-benchmark" aria-label="Permalink to &quot;Performance benchmark&quot;">​</a></h1><p>On 2026-11-20, the same Apple M1 Pro (16 GiB) and headless Chrome 158.0.8127.36 ran all three targets. Each target and workload used three fresh page sessions. Target order rotated between trials.</p><table tabindex="0"><thead><tr><th>Target</th><th>Tested build</th></tr></thead><tbody><tr><td>Upstream playground</td><td>The page reported 1.2.0. Entry asset <code>index-VPntKjiG.js</code> had SHA-256 prefix <code>de04b0fea892</code>. <a href="https://hufe.club/canvas-editor/" target="_blank" rel="noreferrer">Live upstream playground</a></td></tr><tr><td>Initial migration</td><td>Production playground rebuilt from the initial documentation-site revision <code>c5a00d38</code>, with its original defaults.</td></tr><tr><td>Current build</td><td>Production playground built from <code>bb315ee9</code> plus working-tree changes, with the default <code>sync</code> preset and IME preview. Asset hashes and the source diff fingerprint are in the raw log.</td></tr></tbody></table><h2 id="built-in-playgrounds" tabindex="-1">Built-in playgrounds <a class="header-anchor" href="#built-in-playgrounds" aria-label="Permalink to &quot;Built-in playgrounds&quot;">​</a></h2><p>Each playground kept its own document. The driver inserted a test lane at the start of the body and replayed the same actions. Upstream had 2 pages and 729 UTF-16 units. Both migration builds had 5 pages and 1,994 UTF-16 units. This comparison reflects the shipped playgrounds and includes differences in their document workloads.</p><p>Each cell shows pooled <strong>P50 / P95 (ms)</strong> across three trials.</p><table tabindex="0"><thead><tr><th>Metric</th><th style="text-align:right;">Upstream playground</th><th style="text-align:right;">Initial migration</th><th style="text-align:right;">Current build</th></tr></thead><tbody><tr><td>Typing handler</td><td style="text-align:right;">2.2 / 4.3</td><td style="text-align:right;">107.6 / 134.9</td><td style="text-align:right;">44.3 / 89.3</td></tr><tr><td>Backspace handler</td><td style="text-align:right;">1.9 / 4.3</td><td style="text-align:right;">106.4 / 122.1</td><td style="text-align:right;">43.3 / 48.2</td></tr><tr><td>Delete handler</td><td style="text-align:right;">2.4 / 5.2</td><td style="text-align:right;">107.9 / 123.1</td><td style="text-align:right;">43.9 / 63.2</td></tr><tr><td>IME preedit handler</td><td style="text-align:right;">2.1 / 3.9</td><td style="text-align:right;">104.5 / 122.8</td><td style="text-align:right;">0.0 / 0.1</td></tr><tr><td>IME preedit to second rAF</td><td style="text-align:right;">23.4 / 30.8</td><td style="text-align:right;">109.0 / 128.4</td><td style="text-align:right;">84.1 / 283.8</td></tr></tbody></table><h2 id="shared-100-paragraph-document" tabindex="-1">Shared 100-paragraph document <a class="header-anchor" href="#shared-100-paragraph-document" aria-label="Permalink to &quot;Shared 100-paragraph document&quot;">​</a></h2><p>All three pages loaded the same mixed English and Arabic document and edited near the middle. Paper size was 480 × 640 CSS px, margins were 32 px on each side, font size was 16 and zoom was 100%. The body contained 7,699 UTF-16 units before the test lane. Upstream, initial migration and current produced 13, 19 and 19 pages respectively. Each version used its own font resolution and layout pipeline.</p><table tabindex="0"><thead><tr><th>Metric</th><th style="text-align:right;">Upstream playground</th><th style="text-align:right;">Initial migration</th><th style="text-align:right;">Current build</th></tr></thead><tbody><tr><td>Typing handler</td><td style="text-align:right;">3.4 / 5.3</td><td style="text-align:right;">403.2 / 469.4</td><td style="text-align:right;">6.7 / 9.0</td></tr><tr><td>Backspace handler</td><td style="text-align:right;">3.3 / 5.4</td><td style="text-align:right;">418.2 / 482.9</td><td style="text-align:right;">6.6 / 7.8</td></tr><tr><td>Delete handler</td><td style="text-align:right;">3.4 / 5.1</td><td style="text-align:right;">411.7 / 473.4</td><td style="text-align:right;">7.2 / 9.6</td></tr><tr><td>IME preedit handler</td><td style="text-align:right;">3.4 / 4.0</td><td style="text-align:right;">402.8 / 444.7</td><td style="text-align:right;">0.0 / 0.1</td></tr><tr><td>IME preedit to second rAF</td><td style="text-align:right;">24.8 / 31.9</td><td style="text-align:right;">414.9 / 460.4</td><td style="text-align:right;">22.3 / 36.3</td></tr></tbody></table><p>On the shared workload, Backspace handler P95 fell from <strong>482.9 ms</strong> in the initial migration to <strong>7.8 ms</strong> in the current build. Upstream recorded <strong>5.4 ms</strong>. In the built-in playgrounds, IME preedit to second rAF P95 was <strong>30.8 ms</strong> upstream, <strong>128.4 ms</strong> in the initial migration and <strong>283.8 ms</strong> in the current build. The current playground improved the median while its slowest updates took longer. A short handler can leave layout and painting work for later browser frames.</p><h2 id="method-and-reproduction" tabindex="-1">Method and reproduction <a class="header-anchor" href="#method-and-reproduction" aria-label="Permalink to &quot;Method and reproduction&quot;">​</a></h2><ul><li>Viewport 1366 × 720, DPR 1. Each trial warmed up one insertion and deletion, then replayed 12 events each for typing, Backspace and Delete and 7 pinyin preedits before committing “你好”. The driver waited for each keyboard dispatch with at least 50 ms between operations and at least 40 ms between Chrome composition updates.</li><li>Handler duration comes from the <code>input</code> event for typing and preedit and <code>keydown</code> for deletion. Time to the second <code>requestAnimationFrame</code> measures browser scheduling. This run covers automated Chrome composition, with no measurement of hardware key repeat, system candidate windows or display timing.</li><li>All 18 trials checked event counts, final text and caret positions. Each workload and target contributed 36 events per keyboard metric and 21 preedit events.</li></ul><p><a href="../../guide/performance-baselines/playground-comparison-2026-11-20.json">Raw logs for all three targets</a> · <a href="../../guide/performance-baselines/perf01-2026-10-22.json">October 22 initial-migration archive</a></p><p>Build the current playground with <code>npm run docs:build</code>. Export the initial revision into a temporary directory with <code>git archive c5a00d38</code>, reuse the project dependencies and build it with <code>DOCS_BASE=/initial/ node scripts/build-docs-demo.mjs</code>. Serve both production builds at their configured base paths and run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLAYWRIGHT_MODULE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/absolute/path/to/playwright/index.mjs</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BROWSER_EXECUTABLE=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/Applications/Google Chrome.app/Contents/MacOS/Google Chrome&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INITIAL_URL=http://127.0.0.1:3027/initial/playground/ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CURRENT_URL=http://127.0.0.1:3027/canvas-editor/playground/ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/test-playground-benchmark.mjs</span></span></code></pre></div>`,16)])])}const u=e(n,[["render",d]]);export{c as __pageData,u as default};
